                    res = 0
                    for i in range((s_rem // 10) + 1):
                        res += ((-1)**i) * comb(l_rem, i) * comb(s_rem - 10*i + l_rem - 1, l_rem - 1)
                    return res
                index += count_fixed(l - 1, target_sum - first_digit)

    # Count numbers with same length but smaller value
    current_sum = target_sum
    for i in range(length):
        start_digit = 1 if i == 0 else 0
        limit = int(s_target[i])
        for digit in range(start_digit, limit):
            if current_sum - digit >= 0:
                from math import comb
                def count_fixed(l_rem, s_rem):
                    res = 0
                    for j in range((s_rem // 10) + 1):
                        res += ((-1)**j) * comb(l_rem, j) * comb(s_rem - 10*j + l_rem - 1, l_rem - 1)
                    return res
                index += count_fixed(length - 1 - i, current_sum - digit)
        current_sum -= limit
    return index + 1

